/// The pointer and C-string constants, which const evaluation cannot read as integers.
#[test]
fn pointer_constants_hold_their_recorded_values() {
    assert_eq!(
        aterm_win32::Win32::Security::Cryptography::CERT_CHAIN_POLICY_SSL as usize,
        4
    );
    assert_eq!(
        aterm_win32::Win32::Security::Cryptography::CERT_STORE_PROV_MEMORY as usize,
        2
    );
    // SAFETY: the constant is a NUL-terminated literal.
    assert_eq!(
        unsafe {
            std::ffi::CStr::from_ptr(
                aterm_win32::Win32::Security::Cryptography::szOID_PKIX_KP_SERVER_AUTH.cast(),
            )
        }
        .to_str(),
        Ok("1.3.6.1.5.5.7.3.1")
    );
    assert_eq!(
        aterm_win32::Win32::UI::HiDpi::DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE as usize,
        18446744073709551613
    );
    assert_eq!(
        aterm_win32::Win32::UI::HiDpi::DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2 as usize,
        18446744073709551612
    );
    assert_eq!(
        aterm_win32::Win32::UI::WindowsAndMessaging::HWND_BOTTOM as usize,
        1
    );
    assert_eq!(
        aterm_win32::Win32::UI::WindowsAndMessaging::HWND_NOTOPMOST as usize,
        18446744073709551614
    );
    assert_eq!(
        aterm_win32::Win32::UI::WindowsAndMessaging::HWND_TOPMOST as usize,
        18446744073709551615
    );
    assert_eq!(
        aterm_win32::Win32::UI::WindowsAndMessaging::IDC_ARROW as usize,
        32512
    );
    assert_eq!(
        aterm_win32::Win32::UI::WindowsAndMessaging::IDC_HAND as usize,
        32649
    );
    assert_eq!(
        aterm_win32::Win32::UI::WindowsAndMessaging::IDC_IBEAM as usize,
        32513
    );
    assert_eq!(
        aterm_win32::Win32::UI::WindowsAndMessaging::IDC_SIZEALL as usize,
        32646
    );
    assert_eq!(
        aterm_win32::Win32::UI::WindowsAndMessaging::IDC_SIZENS as usize,
        32645
    );
    assert_eq!(
        aterm_win32::Win32::UI::WindowsAndMessaging::IDC_SIZEWE as usize,
        32644
    );
}
